/* ═══════════════════════════════════════════════════════════
   UI NAVIGATION & THEME — NEW ADDITIONS ONLY
   (Physics simulation logic below is untouched)
═══════════════════════════════════════════════════════════ */

function showGameScreen() {
    document.getElementById('landing-screen').classList.remove('active');
    document.getElementById('game-screen').classList.add('active');
}

function showLandingScreen() {
    document.getElementById('game-screen').classList.remove('active');
    document.getElementById('landing-screen').classList.add('active');
}

function toggleTheme(isLight) {
    // Sync both toggles
    document.getElementById('theme-toggle-landing').checked = isLight;
    document.getElementById('theme-toggle-game').checked = isLight;
    document.documentElement.setAttribute('data-theme', isLight ? 'light' : 'dark');
}

function showTab(num) {
    document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.classList.toggle('active', parseInt(btn.dataset.tab) === num);
    });
    document.querySelectorAll('.station-info').forEach(info => {
        info.classList.toggle('active', parseInt(info.dataset.info) === num);
    });
}

/* ═══════════════════════════════════════════════════════════
   ZOOM / SCROLL WHEEL SYSTEM
═══════════════════════════════════════════════════════════ */
const ZOOM_MIN = 0.4;
const ZOOM_MAX = 2.5;
const ZOOM_STEP = 0.1;
let currentZoom = 1.0;

function applyZoom(zoom) {
    currentZoom = Math.min(ZOOM_MAX, Math.max(ZOOM_MIN, zoom));

    const inner = document.getElementById('playground-inner');
    if (inner) {
        inner.style.transform = `scale(${currentZoom})`;
        inner.style.transformOrigin = 'top left';
        // Expand inner to fill outer at any zoom so physics bounds stay correct
        const pct = (1 / currentZoom) * 100;
        inner.style.width = pct + '%';
        inner.style.height = pct + '%';
    }

    // Update label
    const label = document.getElementById('zoom-label');
    if (label) label.textContent = Math.round(currentZoom * 100) + '%';

    // Update thumb position on track
    updateThumbPosition();
}

function updateThumbPosition() {
    const track = document.querySelector('.zoom-track');
    const thumb = document.getElementById('zoom-thumb');
    if (!track || !thumb) return;

    const trackH = track.clientHeight - 12; // 12 = thumb height
    const ratio = 1 - (currentZoom - ZOOM_MIN) / (ZOOM_MAX - ZOOM_MIN);
    thumb.style.top = Math.max(0, Math.min(trackH, ratio * trackH)) + 'px';
}

function initZoomControls() {
    const outer = document.getElementById('playground-outer');
    const zoomIn = document.getElementById('zoom-in');
    const zoomOut = document.getElementById('zoom-out');
    const track = document.querySelector('.zoom-track');
    const thumb = document.getElementById('zoom-thumb');

    if (!outer) return;

    // Mouse wheel scrolls the simulation box up/down (NOT zoom)
    outer.addEventListener('wheel', (e) => {
        e.preventDefault();
        applyScroll(currentScrollY + e.deltaY);
    }, { passive: false });

    // Button clicks
    zoomIn && zoomIn.addEventListener('click', () => applyZoom(currentZoom + ZOOM_STEP));
    zoomOut && zoomOut.addEventListener('click', () => applyZoom(currentZoom - ZOOM_STEP));

    // Click on track to jump zoom
    track && track.addEventListener('click', (e) => {
        if (e.target === thumb) return;
        const rect = track.getBoundingClientRect();
        const ratio = 1 - (e.clientY - rect.top) / rect.height;
        applyZoom(ZOOM_MIN + ratio * (ZOOM_MAX - ZOOM_MIN));
    });

    // Drag thumb
    let dragging = false;
    let dragStartY = 0;
    let dragStartZoom = 1;

    thumb && thumb.addEventListener('mousedown', (e) => {
        dragging = true;
        dragStartY = e.clientY;
        dragStartZoom = currentZoom;
        e.preventDefault();
    });

    document.addEventListener('mousemove', (e) => {
        if (!dragging || !track) return;
        const trackH = track.clientHeight;
        const dy = dragStartY - e.clientY; // up = zoom in
        const zoomDelta = (dy / trackH) * (ZOOM_MAX - ZOOM_MIN);
        applyZoom(dragStartZoom + zoomDelta);
    });

    document.addEventListener('mouseup', () => { dragging = false; });

    // Set initial thumb position
    updateThumbPosition();
}

window.addEventListener('resize', updateThumbPosition);

/* ═══════════════════════════════════════════════════════════
   SCROLL SYSTEM (vertical pan of simulation box)
═══════════════════════════════════════════════════════════ */
let currentScrollY = 0;
const SCROLL_STEP = 40;

function applyScroll(y) {
    const outer = document.getElementById('playground-outer');
    if (!outer) return;
    const maxScroll = Math.max(0, outer.scrollHeight - outer.clientHeight + 200);
    currentScrollY = Math.max(0, Math.min(maxScroll, y));
    outer.scrollTop = currentScrollY;
    updateScrollThumb();
}

function updateScrollThumb() {
    const track = document.getElementById('scroll-track');
    const thumb = document.getElementById('scroll-thumb');
    const outer = document.getElementById('playground-outer');
    if (!track || !thumb || !outer) return;

    const trackH = track.clientHeight - 12;
    const maxScroll = Math.max(1, outer.scrollHeight - outer.clientHeight + 200);
    const ratio = currentScrollY / maxScroll;
    thumb.style.top = Math.max(0, Math.min(trackH, ratio * trackH)) + 'px';
}

function initScrollControls() {
    const scrollUp   = document.getElementById('scroll-up');
    const scrollDown = document.getElementById('scroll-down');
    const track      = document.getElementById('scroll-track');
    const thumb      = document.getElementById('scroll-thumb');
    const outer      = document.getElementById('playground-outer');

    if (!outer) return;

    // Make playground-outer scrollable
    outer.style.overflowY = 'auto';
    outer.style.overflowX = 'hidden';
    // Hide native scrollbar (use custom one)
    outer.style.scrollbarWidth = 'none';

    // Sync scroll thumb when user scrolls (wheel, drag, etc.)
    outer.addEventListener('scroll', () => {
        currentScrollY = outer.scrollTop;
        updateScrollThumb();
    });

    // Button clicks
    scrollUp   && scrollUp.addEventListener('click',   () => applyScroll(currentScrollY - SCROLL_STEP));
    scrollDown && scrollDown.addEventListener('click', () => applyScroll(currentScrollY + SCROLL_STEP));

    // Click on track
    track && track.addEventListener('click', (e) => {
        if (e.target === thumb) return;
        const rect = track.getBoundingClientRect();
        const ratio = (e.clientY - rect.top) / rect.height;
        const outer2 = document.getElementById('playground-outer');
        const maxScroll = Math.max(1, outer2.scrollHeight - outer2.clientHeight + 200);
        applyScroll(ratio * maxScroll);
    });

    // Drag scroll thumb
    let dragging = false;
    let dragStartY = 0;
    let dragStartScroll = 0;

    thumb && thumb.addEventListener('mousedown', (e) => {
        dragging = true;
        dragStartY = e.clientY;
        dragStartScroll = currentScrollY;
        e.preventDefault();
    });

    document.addEventListener('mousemove', (e) => {
        if (!dragging || !track) return;
        const trackH = track.clientHeight;
        const outer2 = document.getElementById('playground-outer');
        const maxScroll = Math.max(1, outer2.scrollHeight - outer2.clientHeight + 200);
        const dy = e.clientY - dragStartY;
        applyScroll(dragStartScroll + (dy / trackH) * maxScroll);
    });

    document.addEventListener('mouseup', () => { dragging = false; });

    updateScrollThumb();
}

