const FOOD_ITEMS = [
    { name: 'Lettuce', icon: '🥬', herbivorous: true, waterSoluble: true },
    { name: 'Carrot', icon: '🥕', herbivorous: true, waterSoluble: true },
    { name: 'Apple', icon: '🍎', herbivorous: true, waterSoluble: true },
    { name: 'Spinach', icon: '🍃', herbivorous: true, waterSoluble: true },
    { name: 'Avocado', icon: '🥑', herbivorous: true, waterSoluble: false },
    { name: 'Nuts', icon: '🥜', herbivorous: true, waterSoluble: false },
    { name: 'Beef', icon: '🥩', herbivorous: false, waterSoluble: true },
    { name: 'Chicken', icon: '🍗', herbivorous: false, waterSoluble: true },
    { name: 'Fish', icon: '🐟', herbivorous: false, waterSoluble: false },
    { name: 'Pork', icon: '🥓', herbivorous: false, waterSoluble: true }
];

let draggedItem = null;
let draggedItemData = null;
let draggedStationType = null;
const playground = document.getElementById('playground');
const stations = [];

// ─── STATION 6 STATE ──────────────────────────────────────────────────────────
let floraAlive = true;

// Create food inventory items
function initFoodInventory() {
    const container = document.getElementById('food-items-container');
    FOOD_ITEMS.forEach(food => {
        const item = document.createElement('div');
        item.className = 'inventory-item';
        item.draggable = true;
        item.textContent = food.name;
        item.dataset.name = food.name;
        item.dataset.herbivorous = food.herbivorous;
        item.dataset.waterSoluble = food.waterSoluble;

        item.addEventListener('dragstart', (e) => {
            draggedItem = 'food';
            draggedItemData = { ...food };
            e.dataTransfer.effectAllowed = 'copy';
        });

        container.appendChild(item);
    });
}

// Station drag handlers
function initStationInventory() {
    const stationTemplates = document.querySelectorAll('.station-template');
    stationTemplates.forEach(template => {
        template.addEventListener('dragstart', (e) => {
            draggedItem = 'station';
            draggedStationType = template.dataset.station;
            e.dataTransfer.effectAllowed = 'copy';
        });
    });
}

// Station 1: Herbivorous check
function checkStation1(element, data, elemRect) {
    for (let station of stations) {
        if (station.dataset.type !== 'station1') continue;

        const stationRect = station.getBoundingClientRect();
        const overlaps = !(elemRect.right < stationRect.left ||
                          elemRect.left > stationRect.right ||
                          elemRect.bottom < stationRect.top ||
                          elemRect.top > stationRect.bottom);

        if (overlaps) {
            if (data.herbivorous) {
                console.log(`${data.name} passed Station 1 (Herbivorous)`);
                station.style.borderColor = '#00ff00';
                setTimeout(() => station.style.borderColor = '#8B4513', 300);
                element.style.backgroundColor = '#4CAF50';
                return true;
            } else {
                console.log(`${data.name} rejected at Station 1 (Not Herbivorous)`);
                station.style.borderColor = '#ff0000';
                setTimeout(() => station.style.borderColor = '#8B4513', 300);
                element.style.backgroundColor = '#f44336';
                return false;
            }
        }
    }
    return null;
}

// Station 2: Solubility check with partition
function checkStation2(element, data, elemRect, physics) {
    for (let station of stations) {
        if (station.dataset.type !== 'station2') continue;

        const stationRect = station.getBoundingClientRect();
        const playRect = playground.getBoundingClientRect();

        const overlaps = !(elemRect.right < stationRect.left ||
                          elemRect.left > stationRect.right ||
                          elemRect.bottom < stationRect.top ||
                          elemRect.top > stationRect.bottom);

        if (overlaps) {
            station.style.borderColor = '#00ff00';
            setTimeout(() => station.style.borderColor = '#4169E1', 300);

            const stationCenterX = (stationRect.left + stationRect.right) / 2 - playRect.left;
            const itemCenterX = physics.x + 20;

            if (data.waterSoluble) {
                console.log(`${data.name} is Water-Soluble - forcing RIGHT`);
                element.style.backgroundColor = '#2196F3';
                if (itemCenterX < stationCenterX) {
                    physics.forceX = 2;
                }
            } else {
                console.log(`${data.name} is Fat-Soluble - forcing LEFT`);
                element.style.backgroundColor = '#FF9800';
                if (itemCenterX > stationCenterX) {
                    physics.forceX = -2;
                }
            }
            return true;
        }
    }
    return null;
}

// ─── STATION 6: MICROBIOME BLOCKADE ───────────────────────────────────────────
function checkStation6(element, physics, elemRect) {
    for (let station of stations) {
        if (station.dataset.type !== 'station6') continue;

        const stationRect = station.getBoundingClientRect();

        const overlaps = !(elemRect.right < stationRect.left ||
                           elemRect.left > stationRect.right ||
                           elemRect.bottom < stationRect.top ||
                           elemRect.top > stationRect.bottom);

        if (overlaps) {
            if (floraAlive) {
                // Flora present: slow the item — simulates water absorption + bacterial resistance
                physics.velocityY *= 0.3;
                physics.velocityX *= 0.5;
                // Visual feedback on station
                station.classList.add('s6-active-flora');
                setTimeout(() => station.classList.remove('s6-active-flora'), 200);
            } else {
                // Flora removed: item rockets through unimpeded
                physics.velocityY *= 1.8;
                // Visual feedback on station
                station.classList.add('s6-no-flora');
                setTimeout(() => station.classList.remove('s6-no-flora'), 200);
            }
            return true;
        }
    }
    return null;
}

function applyAntibiotics() {
    floraAlive = false;

    document.querySelectorAll('.station6').forEach(s6 => {
        const imgAlive = s6.querySelector('.s6-img-alive');
        const imgDead  = s6.querySelector('.s6-img-dead');
        const status = s6.querySelector('.s6-status');
        const btnAntibiotics = s6.querySelector('.btn-antibiotics');
        const btnRestore = s6.querySelector('.btn-restore');
        const splatter = s6.querySelector('.s6-splatter');
        const particles = s6.querySelector('.s6-particles-wrap');

        // Fade out alive image, fade in dead image
        if (imgAlive) {
            imgAlive.classList.add('s6-img-fade-out');
            setTimeout(() => {
                imgAlive.style.display = 'none';
                imgAlive.classList.remove('s6-img-fade-out');
            }, 400);
        }
        if (imgDead) {
            setTimeout(() => {
                imgDead.style.display = 'block';
                imgDead.classList.add('s6-img-fade-in');
                setTimeout(() => imgDead.classList.remove('s6-img-fade-in'), 400);
            }, 300);
        }

        if (status) {
            status.textContent = '\u26a0 FLORA: DESTROYED';
            status.classList.add('status-danger');
        }
        if (splatter) splatter.classList.add('splatter-active');
        if (particles) particles.classList.add('particles-fast');
        if (btnAntibiotics) btnAntibiotics.disabled = true;
        if (btnRestore) btnRestore.disabled = false;
    });

    console.log('Station 6: Antibiotics applied — flora removed.');
}

function restoreFlora() {
    floraAlive = true;

    document.querySelectorAll('.station6').forEach(s6 => {
        const imgAlive = s6.querySelector('.s6-img-alive');
        const imgDead  = s6.querySelector('.s6-img-dead');
        const status = s6.querySelector('.s6-status');
        const btnAntibiotics = s6.querySelector('.btn-antibiotics');
        const btnRestore = s6.querySelector('.btn-restore');
        const splatter = s6.querySelector('.s6-splatter');
        const particles = s6.querySelector('.s6-particles-wrap');

        // Fade out dead image, fade in alive image
        if (imgDead) {
            imgDead.classList.add('s6-img-fade-out');
            setTimeout(() => {
                imgDead.style.display = 'none';
                imgDead.classList.remove('s6-img-fade-out');
            }, 400);
        }
        if (imgAlive) {
            setTimeout(() => {
                imgAlive.style.display = 'block';
                imgAlive.classList.add('s6-img-fade-in');
                setTimeout(() => imgAlive.classList.remove('s6-img-fade-in'), 400);
            }, 300);
        }

        if (status) {
            status.textContent = '✓ FLORA: ACTIVE';
            status.classList.remove('status-danger');
        }
        if (splatter) splatter.classList.remove('splatter-active');
        if (particles) particles.classList.remove('particles-fast');
        if (btnAntibiotics) btnAntibiotics.disabled = false;
        if (btnRestore) btnRestore.disabled = true;
    });

    console.log('Station 6: Flora restored.');
}

// Playground drag events
playground.addEventListener('dragover', (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
});

playground.addEventListener('drop', (e) => {
    e.preventDefault();

    const rect = playground.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    if (draggedItem === 'station') {
        createStation(draggedStationType, x, y);
        draggedItem = null;
        draggedStationType = null;
    } else if (draggedItem === 'food' && draggedItemData) {
        createFoodItem(draggedItemData, x, y);
        draggedItem = null;
        draggedItemData = null;
    }
});

